-- 示範資料（自動產生，勿手改；改 scripts/seed-demo-cats.mts 後重新產生）
-- 5 個中途喵戶、每個 2 隻待領養貓，都開放基本領養問卷。
-- 「小晴的中途貓屋」掛在 jerryairiti@gmail.com，其他 4 個掛在 zingheartkingandfate@gmail.com。兩個帳號都要先在 Meowho 用 Google 登入過一次。
-- 在 Supabase SQL Editor 執行；id 固定，重跑不會重複建立。清除語法在最下面。

do $$
declare jerry uuid; zing uuid;
begin
  select id into jerry from public.meow_profiles where email = 'jerryairiti@gmail.com';
  select id into zing from public.meow_profiles where email = 'zingheartkingandfate@gmail.com';
  if jerry is null then raise exception '找不到 jerryairiti@gmail.com，請先用這個帳號登入 Meowho 一次'; end if;
  if zing is null then raise exception '找不到 zingheartkingandfate@gmail.com，請先用這個帳號登入 Meowho 一次'; end if;


  -- 小晴的中途貓屋
