  values ('d3300000-0000-4000-8000-000000000001', jerry, '小晴的中途貓屋', 'personal_foster', '台中市', '北屯區', '個人中途，家裡有一間專門給貓的房間，每天都會寫照顧日記。', 'public', true, '{"items":["年滿 20 歲或家人同意","不放養","門窗防護","簽切結書","定期追蹤回報"],"note":""}'::jsonb, null)
