id":"pets_vaccinated","section":"pets","text":"家裡的寵物有打預防針嗎？","type":"yesno","options":[],"required":false,"withDetail":true,"prefill":null},{"id":"pets_illness","section":"pets","text":"家裡的寵物有沒有其他疾病？","type":"text","options":[],"required":false,"withDetail":false,"prefill":null},{"id":"experience","section":"pets","text":"過去養寵物的經驗","type":"text","options":[],"required":true,"withDetail":false,"prefill":null},{"id":"space","section":"care","text":"貓咪會養在房間，還是可以整屋自由活動？","type":"single","options":["養在房間","整屋自由活動","其他"],"required":true,"withDetail":false,"prefill":null},{"id":"space_photos","section":"care","text":"請拍幾張貓咪之後活動空間的照片，尤其是門窗。","type":"photo","options":[],"required":true,"withDetail":false,"prefill":null},{"id":"screens","section":"care","text":"願意為貓咪做門窗防護，預防逃脫嗎？","type":"yesno","options":[],"required":true,"withDetail":false,"prefill":null},{"id":"abandon_risk","section":"care","text":"有沒有過敏、小孩、伴侶等可能導致棄養的狀況？","type":"yesno","options":[],"required":true,"withDetail":true,"prefill":null},{"id":"carrier","section":"care","text":"是否同意貓非必要不帶出門，外出時一定使用外出籠或牽繩？","type":"yesno","options":[],"required":true,"withDetail":false,"prefill":null},{"id":"cost_note","section":"cost","text":"一隻貓一個月的飼料、罐頭、貓砂與生活用品大約 4,000 元。看病至少幾百元起跳，小病幾千元，大病兩三萬甚至十萬元都有可能。","type":"note","options":[],"required":false,"withDetail":false,"prefill":null},{"id":"afford_medical","section":"cost","text":"如果牠生病，你能負擔可能非常昂貴的醫療費用嗎？","type":"yesno","options":[],"required":true,"withDetail":false,"prefill":null},{"id":"adjust_period","section":"cost","text":"新貓剛到家可能會叫個不停、需要很多陪伴，你願意給牠一兩週的適應期嗎？","type":"yesno","options":[],"required":true,"withDetail":false,"prefill":null},{"id":"contract","section":"agreement","text":"是否願意配合簽約，並核對身分證件？","type":"yesno","options":[],"required":true,"withDetail":false,"prefill":null}]'::jsonb, true)
